const result = await browserjs(tabId, () => {
  const board = document.querySelector('cg-board');
  const rect = board.getBoundingClientRect();

  function getCoords(px, py) {
    return {
      clientX: rect.left + px,
      clientY: rect.top + py
    };
  }

  function drag(fromX, fromY, toX, toY) {
    const start = getCoords(fromX, fromY);
    const end = getCoords(toX, toY);

    const down = new MouseEvent('mousedown', {
      bubbles: true,
      cancelable: true,
      view: window,
      clientX: start.clientX,
      clientY: start.clientY,
      button: 0,
      buttons: 1
    });

    const move = new MouseEvent('mousemove', {
      bubbles: true,
      cancelable: true,
      view: window,
      clientX: end.clientX,
      clientY: end.clientY,
      button: 0,
      buttons: 1
    });

    const up = new MouseEvent('mouseup', {
      bubbles: true,
      cancelable: true,
      view: window,
      clientX: end.clientX,
      clientY: end.clientY,
      button: 0,
      buttons: 0
    });

    board.dispatchEvent(down);
    document.dispatchEvent(move);
    board.dispatchEvent(up);
  }

  // White rook at 144+36 = 180, 72+36 = 108
  // First star at 144+36 = 180, 216+36 = 252
  drag(180, 108, 180, 252);

  return "dragged";
});

